void printing_combn(int current, int digits, int first_call)
{
    int divisor = 1;

    if (!first_call) {
        my_putchar(',');
        my_putchar(' ');
    }
    for (int i = digits - 1; i >= 0; i--) {
        divisor = 1;
        for (int j = 0; j < i; j++) {
            divisor *= 10;
        }
        my_putchar((current / divisor) % 10 + '0');
    }
}

void my_print_combinations(int n, combination_state_t *state)
{
    combination_state_t next_state;

    if (state->depth == n) {
        printing_combn(state->current, n, state->first_call);
        return;
    }
    for (int i = state->prev + 1; i <= 9; i++) {
        next_state.current = state->current * 10 + i;
        next_state.depth = state->depth + 1;
        next_state.prev = i;
        next_state.first_call = state->first_call;
        my_print_combinations(n, &next_state);
        state->first_call = 0;
    }
}

