{
    combination_state_t initial_state;

    if (n == 1) {
        for (int i = 0; i <= 9; i++) {
            condition(i);
            my_putchar(i + '0');
        }
        my_putchar('\n');
    } else {
        initial_state.current = 0;
        initial_state.depth = 0;
        initial_state.prev = -1;
        initial_state.first_call = 1;
        my_print_combinations(n, &initial_state);
    }
}

